// model.cpp - Decision Tree inference (scikit-learn DecisionTreeClassifier)
// The tree is stored as flat arrays (see model_data.h, generated by the notebook):
//   DT_FEATURE[n]   feature used at node n (-1 = leaf)
//   DT_THRESHOLD[n] go left if x[feature] <= threshold
//   DT_LEFT/RIGHT   child node indices; for a leaf DT_LEFT holds the class
#include "model_api.h"
#include "model_info.h"
#include "model_data.h"

bool model_init(void) { return true; }

int model_predict(const float *x, float *score) {
    int n = 0;
    while (DT_FEATURE[n] >= 0)
        n = (x[DT_FEATURE[n]] <= DT_THRESHOLD[n]) ? DT_LEFT[n] : DT_RIGHT[n];
    if (score) *score = DT_LEAF_PROB[n];
    return DT_LEFT[n];
}

const char *model_name(void) { return MODEL_NAME; }
size_t model_flash_bytes(void) {
    return sizeof(DT_FEATURE) + sizeof(DT_THRESHOLD) + sizeof(DT_LEFT) + sizeof(DT_RIGHT) +
           sizeof(DT_LEAF_PROB);
}
size_t model_arena_bytes(void) { return 0; }
